"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
  type ComponentProps,
  type Dispatch,
  type SetStateAction,
} from "react";
import {
  DropdownMenu as BaseMenu,
  DropdownMenuTrigger as BaseTrigger,
  DropdownMenuContent as BaseContent,
  DropdownMenuSub as BaseSub,
  DropdownMenuSubContent as BaseSubContent,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { useLiquidElement } from "@/lib/liquid/motion";
import {
  MenuMorph,
  MenuSession,
  coverPlacement,
  measureAnchor,
  sameAnchor,
  type Anchor,
} from "@/lib/liquid/menu-morph";
import "./liquid.css";
export {
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuLabel,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuShortcut,
  DropdownMenuSubTrigger,
  DropdownMenuPortal,
} from "@/components/ui/dropdown-menu";

type SetAnchor = Dispatch<SetStateAction<Anchor | null>>;
type MenuContextValue = {
  session: MenuSession;
  anchor: Anchor | null;
  setAnchor: SetAnchor;
  open?: boolean;
};

// Content rendered inside a plain base menu still works; it opens beside its trigger, unmorphed.
const detached: MenuContextValue = {
  session: new MenuSession(),
  anchor: null,
  setAnchor: () => {},
};
const MenuContext = createContext<MenuContextValue>(detached);
const SubContext = createContext<boolean | undefined>(undefined);

/**
 * A menu's open state, controlled or not. Liquid parts read it in the same render as the
 * primitive, so the closing keyframes start as the menu closes; were they any later, the
 * primitive would unmount the panel at once. Extra arguments reach `onChange` untouched.
 */
function useOpenState<Change extends (open: boolean, ...details: never[]) => void>(
  controlled: boolean | undefined,
  initial: boolean | undefined,
  onChange: Change | undefined,
) {
  const [uncontrolled, setUncontrolled] = useState(initial ?? false);
  const change = useCallback(
    (next: boolean, ...details: never[]) => {
      setUncontrolled(next);
      onChange?.(next, ...details);
    },
    [onChange],
  );
  return [controlled ?? uncontrolled, change as Change] as const;
}

/** A panel's `data-liquid-state`, known only inside a liquid menu. */
function stateOf(open: boolean | undefined) {
  if (open === undefined) return undefined;
  return open ? "open" : "closed";
}

function remeasure(element: HTMLElement, setAnchor: SetAnchor) {
  const next = measureAnchor(element);
  setAnchor((previous) => (sameAnchor(previous, next) ? previous : next));
}

export function DropdownMenu({
  open,
  defaultOpen,
  onOpenChange,
  ...props
}: ComponentProps<typeof BaseMenu>) {
  const [session] = useState(() => new MenuSession());
  const [anchor, setAnchor] = useState<Anchor | null>(null);
  const [state, setOpen] = useOpenState(open, defaultOpen, onOpenChange);
  const value = useMemo(
    () => ({ session, anchor, setAnchor, open: state }),
    [session, anchor, state],
  );
  return (
    <MenuContext.Provider value={value}>
      <BaseMenu open={state} onOpenChange={setOpen} {...props} />
    </MenuContext.Provider>
  );
}

export function DropdownMenuSub({
  open,
  defaultOpen,
  onOpenChange,
  ...props
}: ComponentProps<typeof BaseSub>) {
  const [state, setOpen] = useOpenState(open, defaultOpen, onOpenChange);
  return (
    <SubContext.Provider value={state}>
      <BaseSub open={state} onOpenChange={setOpen} {...props} />
    </SubContext.Provider>
  );
}

export function DropdownMenuTrigger({ ref, ...props }: ComponentProps<typeof BaseTrigger>) {
  const { session, setAnchor } = useContext(MenuContext);
  const [node, mergedRef] = useLiquidElement(ref);
  useEffect(
    () => (node ? session.attach(node, () => remeasure(node, setAnchor)) : undefined),
    [session, setAnchor, node],
  );
  return <BaseTrigger ref={mergedRef} {...props} />;
}

function useMenuMorph(node: HTMLDivElement | null, session?: MenuSession, covering = false) {
  useEffect(() => {
    if (!node) return;
    const anchor = () =>
      session?.anchor() ?? document.getElementById(node.getAttribute("aria-labelledby") ?? "");
    const morph = new MenuMorph(node, anchor, covering);
    return () => morph.destroy();
  }, [node, session, covering]);
}

type LiquidContentProps = ComponentProps<typeof BaseContent> & {
  /** Open over the trigger and grow out of it, as iOS does. Set `false` to open beside it. */
  overlap?: boolean;
};

export function DropdownMenuContent({
  className,
  children,
  side = "bottom",
  sideOffset,
  align,
  overlap = true,
  ref,
  ...props
}: LiquidContentProps) {
  const { session, anchor, setAnchor, open } = useContext(MenuContext);
  const [node, mergedRef] = useLiquidElement(ref);
  const cover = overlap ? anchor : null;
  // Covers opens that did not come from the trigger, e.g. a controlled `open`.
  useLayoutEffect(() => {
    const trigger = session.anchor();
    if (node && overlap && trigger) remeasure(trigger, setAnchor);
  }, [node, overlap, session, setAnchor]);
  useMenuMorph(node, session, !!cover);
  useEffect(() => (node ? session.guard(node) : undefined), [node, session]);
  return (
    <BaseContent
      ref={mergedRef}
      side={side}
      collisionPadding={8}
      {...coverPlacement(cover, side, { sideOffset, align })}
      className={cn("liquid-surface liquid-menu", className)}
      data-liquid-state={stateOf(open)}
      {...props}
    >
      <div className="liquid-menu-body">{children}</div>
    </BaseContent>
  );
}

export function DropdownMenuSubContent({
  className,
  children,
  ref,
  ...props
}: ComponentProps<typeof BaseSubContent>) {
  const open = useContext(SubContext);
  const [node, mergedRef] = useLiquidElement(ref);
  useMenuMorph(node);
  return (
    <BaseSubContent
      ref={mergedRef}
      className={cn("liquid-surface liquid-menu", className)}
      data-liquid-state={stateOf(open)}
      {...props}
    >
      <div className="liquid-menu-body">{children}</div>
    </BaseSubContent>
  );
}

/*
 * Material defaults live on the root, so a value set on any ancestor reaches its glass. Where
 * --liquid-accent is unset, the accent is #155dfc, oklch(54.6% 0.245 262.881): white text on it
 * is 5.3:1, above AA's 4.5:1.
 */
:root {
  --liquid-blur: 20px;
  --liquid-tint: 0.22;
  --liquid-ink: #172323;
  --liquid-fill: 255 255 255;
}
.liquid-surface {
  position: relative;
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / var(--liquid-tint));
  border: 1px solid rgb(255 255 255 / 0.65);
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / 0.9),
    inset 0 -1px 1px rgb(255 255 255 / 0.25),
    inset 2px 0 5px rgb(255 255 255 / 0.18),
    0 8px 28px rgb(0 20 25 / 0.14);
  transition:
    background 200ms ease,
    box-shadow 200ms ease;
}
/* No focus rings. Keyboard focus tints the glass instead, so it stays visible without one. */
.liquid-surface:focus-visible,
.liquid-tab:focus-visible,
.liquid-toolbar-button:focus-visible,
.liquid-tab-bar :is(button, input):focus-visible {
  outline: none;
}
.liquid-surface:not(.liquid-interactive, [role="menu"], [role="dialog"]):focus-visible {
  background-color: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + 0.2));
}
.liquid-interactive {
  position: relative;
  translate: var(--liquid-x, 0px) var(--liquid-y, 0px);
  scale: var(--liquid-scale-x, 1) var(--liquid-scale-y, 1);
  /* The spring owns translate/scale; consumers still own transform. */
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    opacity 140ms ease;
}
/* Keyboard focus tints the glass, like a highlighted menu item. */
.liquid-interactive:is(:focus-visible, :has(> .liquid-tab-bar-toggle:focus-visible)):not(
    [data-liquid-variant="prominent"]
  ) {
  background-color: color-mix(
    in srgb,
    var(--liquid-accent, #155dfc) 18%,
    rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.3))
  );
}
/* Content morph: new content condenses out of light while the width springs. */
.liquid-interactive[data-liquid-morphing] {
  overflow: clip;
}
.liquid-interactive[data-liquid-morph="a"] {
  animation: liquid-ink-in-a 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="b"] {
  animation: liquid-ink-in-b 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="a"] > svg {
  animation: liquid-glyph-in-a 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
.liquid-interactive[data-liquid-morph="b"] > svg {
  animation: liquid-glyph-in-b 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
@keyframes liquid-ink-in-a {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-ink-in-b {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-glyph-in-a {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
@keyframes liquid-glyph-in-b {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
.liquid-button {
  border-radius: 999px;
  min-height: 44px;
  font-weight: 600;
  padding-inline: 24px;
}
.liquid-button:hover:not(:disabled) {
  background: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + 0.1));
  box-shadow:
    inset 0 1px 2px white,
    inset 0 -1px 2px rgb(190 224 255 / 0.5),
    0 8px 28px rgb(0 20 25 / 0.14);
}
.liquid-button[data-size^="icon"] {
  padding-inline: 0;
  min-width: 44px;
}
.liquid-button[data-liquid-variant="destructive"] {
  --liquid-ink: #a20c22;
  --liquid-fill: 255 200 208;
}
.liquid-button[data-liquid-variant="link"] {
  text-decoration: underline;
}
.liquid-button[data-liquid-variant="secondary"] {
  background: rgb(var(--liquid-fill) / 0.55);
}
.liquid-button[aria-expanded="true"] > svg {
  rotate: 180deg;
}
.liquid-button > svg {
  transition: rotate 350ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* Segmented tabs and toolbars share one lens. */
.liquid-tabs {
  border-radius: 999px;
  padding: 5px;
  height: 52px;
  gap: 3px;
  isolation: isolate;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    scale 460ms cubic-bezier(0.25, 1.45, 0.45, 1);
}
.liquid-tabs[aria-orientation="vertical"] {
  height: auto;
  border-radius: 26px;
  touch-action: pan-x;
}
/* The whole bar swells a little while a finger is on it. */
.liquid-tabs[data-liquid-pressed] {
  scale: 1.025;
  transition-duration: 200ms, 200ms, 240ms;
}
.liquid-tab {
  position: relative;
  color: var(--liquid-ink);
  /* The base trigger borders the active tab in dark mode, and ahead of the travelling lens. */
  border-color: transparent;
  border-radius: 999px;
  padding-inline: 22px;
  height: 40px;
  background: transparent;
  transition: color 180ms ease;
}
.liquid-tab[aria-selected="true"] {
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / 0.58);
  box-shadow: inset 0 1px 1px rgb(255 255 255 / 0.8);
}
.liquid-tabs[data-liquid-indicator] .liquid-tab[aria-selected="true"] {
  background: transparent;
  box-shadow: none;
}
.liquid-tab:hover:not(:disabled) {
  color: var(--liquid-ink);
}
/* The base tabs draw a ring on focus; glass has none. */
.liquid-tab:focus-visible:not([aria-selected="true"]) {
  box-shadow: none;
  background: rgb(var(--liquid-fill) / 0.3);
}
/* An iOS tab bar: add `liquid-tabbar` to a TabsList to stack icons over labels. */
.liquid-tabbar {
  height: 66px;
  padding: 5px;
  gap: 0;
}
.liquid-tabbar .liquid-tab {
  height: 54px;
  min-width: 88px;
  flex-direction: column;
  gap: 3px;
  padding-inline: 14px;
  font-size: 11px;
  font-weight: 600;
}
.liquid-tabbar .liquid-tab svg {
  width: 23px;
  height: 23px;
}
.liquid-lens {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  overflow: hidden;
  border-radius: 999px;
  pointer-events: none;
  /* At rest: a frosted pill. Lifted: clear glass with a bright, faintly chromatic rim. */
  background:
    linear-gradient(
      135deg,
      rgb(255 255 255 / calc(0.2 * (1 - var(--liquid-lift, 0)))),
      transparent 55%
    ),
    rgb(
      var(--liquid-lens-fill, 255 255 255) /
        calc(var(--liquid-lens-alpha, 0.5) * (1 - 0.8 * var(--liquid-lift, 0)))
    );
  box-shadow:
    inset 0 1px 1.5px rgb(255 255 255 / calc(0.75 + 0.25 * var(--liquid-lift, 0))),
    inset 0 -1px 1.5px rgb(255 255 255 / calc(0.25 + 0.5 * var(--liquid-lift, 0))),
    inset 2px 0 3px -1px rgb(255 110 190 / calc(0.55 * var(--liquid-lift, 0))),
    inset -2px 0 3px -1px rgb(70 200 255 / calc(0.55 * var(--liquid-lift, 0)));
  opacity: 0;
  transition: opacity 200ms ease;
}
[data-liquid-indicator] > .liquid-lens {
  opacity: 1;
}
/* Focus on the selected item tints the lens over it. */
[data-liquid-indicator]:has(
    > :is([aria-selected="true"], [aria-pressed="true"], [aria-current]):focus-visible
  )
  > .liquid-lens {
  --liquid-lens-fill: 0 122 255;
  --liquid-lens-alpha: 0.2;
}
/* An inert copy of the list, magnified and tinted inside the lens. */
.liquid-lens > .liquid-lens-optics {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  color: var(--liquid-lens-ink, var(--liquid-accent, var(--liquid-system-accent, #155dfc)));
  /* The copy carries the list's classes; strip its material, whichever rule set it. */
  background: none !important;
  border-color: transparent !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: none;
  translate: none;
  scale: none;
  transition: none;
  animation: none;
  pointer-events: none;
}
.liquid-lens-optics * {
  color: inherit !important;
  text-shadow: none !important;
  transition: none !important;
  animation: none !important;
}
.liquid-lens-optics > * {
  background: transparent !important;
  box-shadow: none !important;
  border-color: transparent !important;
  translate: none !important;
  scale: none !important;
}
/* Once the lens has landed the copy stands in for the selected label. */
[data-liquid-lens="rest"]
  :is(.liquid-tab[aria-selected="true"], .liquid-toolbar-button[aria-pressed="true"]):not(
    .liquid-lens *
  ) {
  color: transparent;
  text-shadow: none;
}
.liquid-menu {
  --liquid-menu-x: 0px;
  --liquid-menu-y: -10px;
  --liquid-menu-scale-x: 0.8;
  --liquid-menu-scale-y: 0.6;
  --liquid-menu-radius: 70px;
  --liquid-menu-mid-x: 0px;
  --liquid-menu-mid-y: -5px;
  --liquid-menu-mid-scale-x: 0.7;
  --liquid-menu-mid-scale-y: 0.7;
  border-radius: 22px;
  padding: 6px;
  min-width: 220px;
  background: rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.68));
  transform-origin: center;
  transition: background 200ms ease;
  /*
   * The panel clips and its body scrolls. The body arrives magnified as the panel forms; were
   * the panel the scroller, that growth would flash scrollbars during every entrance.
   */
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.liquid-menu [role^="menuitem"] {
  min-height: 40px;
  border-radius: 15px;
  color: inherit;
  transition: background 140ms ease;
}
/* Primitives move focus to the item under the pointer as well as the keyboard's. */
.liquid-menu [role^="menuitem"]:focus {
  background: rgb(0 122 255 / 0.16);
}
.liquid-menu [data-variant="destructive"] {
  color: #c52238;
}
/* Fills the panel, whose max height the base component sets from its primitive, and scrolls. */
.liquid-menu-body {
  flex: 0 1 auto;
  min-height: 0;
  transform-origin: 50% 40%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.liquid-menu[data-liquid-state="open"]:not([data-liquid-morph="ready"]) {
  opacity: 0;
}
.liquid-menu[data-liquid-state="open"][data-liquid-morph="ready"] {
  animation: liquid-menu-unfold var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-liquid-state="open"][data-liquid-morph="ready"] > .liquid-menu-body {
  animation: liquid-menu-body-in var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-liquid-state="closed"] {
  animation: liquid-menu-fold 320ms both;
  pointer-events: none;
}
.liquid-menu[data-liquid-state="closed"] > .liquid-menu-body {
  animation: liquid-menu-body-out 130ms ease-in both;
}
/* The trigger swells into a round droplet, which stretches into the panel. */
@keyframes liquid-menu-unfold {
  0% {
    opacity: 0.7;
    transform: translate(var(--liquid-menu-x), var(--liquid-menu-y))
      scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y));
    border-radius: var(--liquid-menu-radius);
    animation-timing-function: cubic-bezier(0.3, 0.1, 0.5, 1);
  }
  26% {
    opacity: 1;
    transform: translate(var(--liquid-menu-mid-x), var(--liquid-menu-mid-y))
      scale(var(--liquid-menu-mid-scale-x), var(--liquid-menu-mid-scale-y));
    border-radius: 50%;
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  62% {
    opacity: 1;
    transform: translate(0, 0) scale(1.025, 1.04);
    border-radius: 22px;
    animation-timing-function: cubic-bezier(0.3, 0, 0.3, 1);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    border-radius: 22px;
  }
}
/* Content arrives magnified and out of focus, as if seen through the forming lens. */
@keyframes liquid-menu-body-in {
  0%,
  16% {
    opacity: 0;
    transform: scale(1.3);
    filter: blur(10px);
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  55% {
    opacity: 1;
    transform: scale(1.05);
    filter: blur(1.5px);
  }
  100% {
    opacity: 1;
    transform: none;
    filter: none;
  }
}
@keyframes liquid-menu-body-out {
  to {
    opacity: 0;
    transform: scale(0.94);
    filter: blur(6px);
  }
}
/* The panel collapses into a droplet that is drawn back into its trigger. */
@keyframes liquid-menu-fold {
  0% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    border-radius: 22px;
    animation-timing-function: cubic-bezier(0.5, 0, 0.7, 0.4);
  }
  45% {
    opacity: 1;
    transform: translate(var(--liquid-menu-mid-x), var(--liquid-menu-mid-y))
      scale(
        calc(var(--liquid-menu-mid-scale-x) * 0.78),
        calc(var(--liquid-menu-mid-scale-y) * 0.95)
      );
    border-radius: 50%;
    animation-timing-function: cubic-bezier(0.3, 0, 0.2, 1);
  }
  100% {
    opacity: 0;
    transform: translate(var(--liquid-menu-x), var(--liquid-menu-y))
      scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y));
    border-radius: var(--liquid-menu-radius);
  }
}
/* A trigger covered by its menu becomes the menu, then reappears as the droplet lands. */
[data-liquid-covered] {
  transition: opacity 140ms ease 120ms;
}
[data-liquid-covered][aria-expanded="true"] {
  opacity: 0;
  transition: opacity 90ms ease;
}
/* The shell toolbars and tab bars share: capsules of glass, and round buttons beside them. */
.liquid-toolbar,
.liquid-tab-bar {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  max-width: 100%;
}
.liquid-toolbar[aria-orientation="vertical"] {
  flex-direction: column;
}
.liquid-toolbar-group {
  display: flex;
  align-items: center;
  padding: 6px;
  border-radius: 999px;
  gap: 4px;
  isolation: isolate;
}
.liquid-toolbar-group[data-orientation="vertical"] {
  flex-direction: column;
}
/* Toolbar buttons are liquid Buttons: ghost on a group's glass, glass of their own outside. */
.liquid-toolbar-button {
  display: grid;
  place-items: center;
  width: 44px;
  min-width: 0;
  height: 44px;
  min-height: 0;
  padding: 0;
  border-radius: 50%;
}
.liquid-toolbar-button svg {
  width: 21px;
  height: 21px;
}
/* An icon, not a disclosure chevron: it stays put while its menu is open. */
.liquid-toolbar .liquid-button > svg {
  rotate: none;
}
.liquid-toolbar-group .liquid-toolbar-button:hover:not(:disabled),
.liquid-toolbar-group .liquid-toolbar-button[aria-pressed="true"] {
  background: rgb(255 255 255 / 0.18);
  box-shadow: none;
}
.liquid-toolbar-group[data-liquid-indicator] .liquid-toolbar-button[aria-pressed="true"] {
  background: transparent;
}
.liquid-toolbar-button:disabled {
  opacity: 0.5;
}
/* A button of its own is as tall as a group: 44px buttons, 6px padding, 1px border. */
.liquid-toolbar > .liquid-toolbar-button {
  width: 58px;
  height: 58px;
}
.liquid-toolbar > .liquid-toolbar-button svg {
  width: 22px;
  height: 22px;
}
.liquid-toolbar-separator {
  flex: none;
  height: 20px;
  width: 1px;
  background: rgb(255 255 255 / 0.4);
  margin-inline: 3px;
}
.liquid-toolbar-separator[aria-orientation="horizontal"] {
  height: 1px;
  width: 20px;
  margin: 3px 0;
}
/* A tab bar with a search button beside it (iOS 26 search tab, button appearance). */
.liquid-tab-bar:has(.liquid-tabbar) {
  --liquid-tab-bar-circle: 68px;
}
.liquid-tab-bar[data-searching] {
  width: var(--liquid-tab-bar-width, auto);
}
.liquid-tab-bar-items {
  flex: none;
  min-width: 0;
  display: flex;
  border-radius: 999px;
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    scale 460ms cubic-bezier(0.25, 1.45, 0.45, 1);
}
/* The glass is the wrapper's, so the tabs inside it can collapse with it. */
.liquid-tab-bar-items > .liquid-tab-bar-tabs > .liquid-surface {
  background: none;
  border-color: transparent;
  box-shadow: none;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
.liquid-tab-bar-items:has([data-liquid-pressed]) {
